import itertools


def _routes(data, policy):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    source = data["source"]
    coupons = data["coupons"]
    deadline = data["deadline"]
    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and (
                policy["coupon_rule"] == "at_most" or used == coupons):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(depart + edge["duration"], used)]
            if used < coupons:
                duration = max(policy["minimum_duration"],
                               edge["duration"] - edge.get("discount", 0))
                options.append((depart + duration, used + 1))
            for arrival, next_used in options:
                if arrival > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if next_node == required_node:
                        next_mask |= 1 << i
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    rows = {}
    for name in names:
        by_version = {row["version"]: row for row in packages[name]}
        rows[name] = by_version
        allowed = [-1]
        for version in sorted(by_version):
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            allowed.append(version)
        choices.append(allowed)

    best_vector = None
    best = None
    for vector in itertools.product(*choices):
        selected = dict(zip(names, vector))
        valid = True
        for name, (low, high) in roots.items():
            version = selected[name]
            if version < 0 or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in names if selected[name] >= 0}
        for name in graph:
            row = rows[name][selected[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = selected[other]
                if version < 0 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(graph):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in graph):
            continue

        if best_vector is None or vector < best_vector:
            best_vector = vector
            best = {name: version for name, version in selected.items()
                    if version >= 0}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in itertools.combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


